import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { ProfileComponent } from '../../../shared/components/profile/profile.component';
import { CasecardComponent } from '../../../shared/components/casecard/casecard.component';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { MatMenuModule } from '@angular/material/menu';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { AdmindashboardService } from '../../services/admin-dashboard/admindashboard.service';
// import { NgScrollbarReachedModule } from 'ngx-scrollbar/reached-event';
import { SkeletonComponent } from '../../../shared/components/skeleton/skeleton.component';
import { adminCaseData, updateAcrchivReq, updateAcrchivResponce } from '../../interfaces/admindashboard.interface';
import { UserDetail } from '../../../core/interfaces/login.interface';
import { HeaderService } from '../../../core/services/header/header.service';
import { NgScrollReached } from 'ngx-scrollbar/reached-event';
import { FormsModule } from '@angular/forms';
@Component({
  selector: 'app-admindashboard',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [],
  imports: [CommonModule, FormsModule, ProfileComponent, CasecardComponent, IconComponent, SkeletonComponent,
    ButtonComponent, MatMenuModule, NgScrollbarModule, NgScrollReached
  ],
  templateUrl: './admindashboard.component.html',
  styleUrl: './admindashboard.component.scss'
})
export class AdmindashboardComponent {
  userdetail: UserDetail;
  caselist: adminCaseData[] = [];
  reached: string = 'S';
  scrolled: boolean = false;
  loding: boolean = true;
  isNoMoreData: boolean = false;
  nPageNumber: number = 1;
  cSearch: string = '';
  constructor(private ss: SecureStorageService, private aDash: AdmindashboardService, private cf: CommonfunctionService,
    private cd: ChangeDetectorRef, private hs: HeaderService) { }

  async ngOnInit() {
    this.userdetail = await this.ss.getUserInfo();
    this.getCaselist()
    this.loding = false;
    this.cd.detectChanges();
  }

  async getCaselist() {
    debugger
    if (this.cSearch.length > 0) {
      this.caselist = [];
      this.nPageNumber = 1;

    }
    this.caselist = await this.aDash.getDashboardlist(this.nPageNumber, this.cSearch);
    this.cd.detectChanges();
  }


  async onReachEnd() {

    if (this.loding || this.isNoMoreData) {
      return;
    }
    this.loding = true;
    try {
      const nextPageNumber = this.nPageNumber + 1;
      const nextList = await this.aDash.getDashboardlist(nextPageNumber, this.cSearch);
      if (nextList.length) {
        this.caselist = [...this.caselist, ...nextList];
        this.nPageNumber = nextPageNumber;
      } else {
        this.isNoMoreData = true;
      }
    } catch (error) {
      console.error('Error fetching the next page of the dashboard list', error);
    } finally {
      this.loding = false;
      this.cd.detectChanges();
    }
  }

  chieldEmit(event, x) {
    if (event == 'EDIT') {
      var mdl = { id: x.nCaseid };
      this.cf.goto('/casebuilder/casecreation', mdl)
    } else if (event == 'VIEW-TICKET') {
      this.cf.goto('/admin/tickets', { id: x.nCaseid })
    } else if (event == 'ARCHIVE-TRUE') {
      this.update_archivecase(x.nCaseid, true);
    } else if (event == 'ARCHIVE-FALSE') {
      this.update_archivecase(x.nCaseid, false);
    }
  }

  onScroll(flag, ev) {
    const threshold = 10;
    const element = ev.target;
    const scrollTop = element.scrollLeft;
    const scrollHeight = element.scrollWidth;
    const clientHeight = element.clientWidth;

    if (scrollHeight - scrollTop <= clientHeight + threshold) {
      this.reached = 'E';  // Close to the end
    } else if (scrollTop === 0) {
      this.reached = 'S';  // At the start
    } else {
      this.reached = 'M';  // In the middle
    }
  }

  GoToNewCase() {
    this.cf.goto('/casebuilder/casecreation', { id: 0 });
  }

  viewArchive() {

    this.cf.goto('/admin/archivecases');
  }

  goTodashboard() {
    this.cf.goto('/user/dashboard');
  }


  async update_archivecase(nCaseid, isArchived) {
    var mdl: updateAcrchivReq = { nCaseid: nCaseid, bIsarchived: isArchived }
    const res = await this.aDash.update_archivecase(mdl);
    if (res) {
      var ind = this.caselist.findIndex(x => x.nCaseid == nCaseid)
      this.caselist.splice(ind, 1);
      this.cd.detectChanges();
    }
  }



  async searchCase() {
    this.nPageNumber = 1;
    this.caselist = await this.aDash.getDashboardlist(this.nPageNumber, this.cSearch);
    this.cd.detectChanges();
  }

  viewOCRQueue() {
    this.cf.goto('/ocrlist');
  }

}
